sys_script_include.script:
var Cisco_Secure_Access_App_Approval_Processing_Private_Resources = Class.create();
Cisco_Secure_Access_App_Approval_Processing_Private_Resources.prototype = {
	initialize: function () {
	},

	process: function () {
		try {
			gs.info("[Cisco Secure Access - PR] Starting looped CMDB insert from Private Resources...");

			// Step 1: Find latest incident for each resource_id
			var incGR = new GlideRecord('incident');
			incGR.addQuery('short_description', 'CONTAINS', 'Private Resource Approval Required');
			incGR.orderByDesc('sys_created_on');
			incGR.query();

			var latestByResourceId = {};

			while (incGR.next()) {
				var resIdMatch = incGR.description ? incGR.description.match(/Resource ID:\s*(\S+)/) : null;
				if (!resIdMatch) continue;
				var resourceId = resIdMatch[1].trim();

				// Only keep the latest incident sys_id per resource
				if (!latestByResourceId[resourceId]) {
					latestByResourceId[resourceId] = incGR.getUniqueValue();
				}
			}

			// Step 2: Update private resource approval_status from latest incident
			for (var resourceId in latestByResourceId) {
				var inc = new GlideRecord('incident');
				if (!inc.get(latestByResourceId[resourceId])) continue;
				var closeCode = (inc.close_code || inc.resolution_code || "").toLowerCase();
				gs.info("[DEBUG] Resource ID=" + resourceId + " closeCode=" + closeCode);
				var decision = "";
				if (closeCode.indexOf("approved") !== -1) decision = "Allow";
				else if (closeCode.indexOf("rejected") !== -1) decision = "Block";
				if (!decision) continue;

				// Update private resource
				var prGR = new GlideRecord('u_cisco_secure_access_private_resources');
				prGR.addQuery('u_resource_id', resourceId);
				prGR.query();
				if (prGR.next()) {
					prGR.u_approval_status = decision;
					prGR.u_status = inc.state == 7 ? 'Closed' : 'Resolved';
					prGR.update();
					gs.info("[Cisco Secure Access - PR] Updated private resource " + resourceId + " approval_status to " + decision + " and status to " + prGR.u_status);
				}
			}

			// Step 3: Insert into Application table
			var prGR2 = new GlideRecord('u_cisco_secure_access_private_resources');
			prGR2.query();

			var total = 0, inserted = 0, skipped = 0, mismatched = 0;
			while (prGR2.next()) {
				total++;
				// Only insert if approval_status is Allow or Block
				if (!prGR2.u_approval_status || (prGR2.u_approval_status != "Allow" && prGR2.u_approval_status != "Block")) {
					gs.info("[Cisco Secure Access - PR] Skipping resource_id=" + prGR2.u_resource_id + " due to approval_status=" + prGR2.u_approval_status);
					continue;
				}

				// Check if already in Application table
				var cmdbCheck = new GlideRecord("u_cmdb_ci_application");
				cmdbCheck.addQuery('u_resource_id', prGR2.u_resource_id);
				cmdbCheck.query();
				if (cmdbCheck.next()) {
					gs.info("[CMDB SKIP] Resource ID=" + prGR2.u_resource_id + " already exists in Application. Skipping.");
					skipped++;
					continue;
				}

				// Insert
				var cmdbGR = new GlideRecord("u_cmdb_ci_application");
				cmdbGR.initialize();
				cmdbGR.u_resource_id = prGR2.u_resource_id;
				cmdbGR.name = prGR2.u_name.toString().trim();
				cmdbGR.approval_status = prGR2.u_approval_status;
				cmdbGR.description = prGR2.u_description;
				cmdbGR.status = prGR2.u_status;
				cmdbGR.created_at = prGR2.u_created_at;
				cmdbGR.created_by = prGR2.u_created_by;
				// Metadata
				cmdbGR.sys_created_on = prGR2.sys_created_on;
				cmdbGR.sys_created_by = prGR2.sys_created_by;
				cmdbGR.sys_updated_on = prGR2.sys_updated_on;
				cmdbGR.sys_updated_by = prGR2.sys_updated_by;
				cmdbGR.public_or_private = "Private";

				var sysId = cmdbGR.insert();
				if (sysId) {
					gs.info("[CMDB INSERT] Resource ID=" + prGR2.u_resource_id + " inserted into  Application. Sys ID=" + sysId);

					// Fetch and compare after insert
					var verifyGR = new GlideRecord("u_cmdb_ci_application");
					if (verifyGR.get(sysId)) {
						var match =
							(verifyGR.u_resource_id == prGR2.u_resource_id) &&
							(verifyGR.name == prGR2.u_name) &&
							(verifyGR.approval_status == prGR2.u_approval_status) &&
							(verifyGR.status == prGR2.u_status);
						gs.info("match =:" + match);
						if (!match) {
							gs.warn("[VERIFY] Data mismatch for Resource ID=" + prGR2.u_resource_id);
							mismatched++;
						}
					} else {
						gs.warn("[VERIFY] Failed to fetch inserted record for Resource ID=" + prGR2.u_resource_id);
					}
					inserted++;
				} else {
					gs.warn("[CMDB INSERT] Failed to insert Resource ID=" + prGR2.u_resource_id + " into  Application.");
				}
			}

			gs.info("[Cisco Secure Access - PR] Summary: Total processed: " + total + ", Inserted: " + inserted + ", Skipped: " + skipped + ", Mismatched: " + mismatched);

			// --- After CMDB insert loop ---

			// 1. Dynamically fetch all active resource groups
			var groupMap = {};
			var groupGR = new GlideRecord('u_cisco_secure_access_private_resources_group');
			groupGR.addQuery('u_active_status', 'Active');
			groupGR.query();
			while (groupGR.next()) {
				var groupName = groupGR.u_name + "";
				groupMap[groupName] = {
					id: groupGR.u_resource_group_id + "",
					desc: groupGR.u_description + ""
				};
			}

			// 2. Gather resource IDs for each group from the CMDB table
			var groupResourceIds = {};
			var cmdbGR = new GlideRecord('u_cmdb_ci_application');
			cmdbGR.query();
			while (cmdbGR.next()) {
				var status = cmdbGR.approval_status + "";
				var resourceId = parseInt(cmdbGR.u_resource_id, 10);
				// Map resource IDs to group by status
				Object.keys(groupMap).forEach(function(groupName) {
					if (status === "Allow" && groupName.toLowerCase().indexOf("allow") !== -1) {
						if (!groupResourceIds[groupName]) groupResourceIds[groupName] = [];
						groupResourceIds[groupName].push(resourceId);
					}
					if (status === "Block" && groupName.toLowerCase().indexOf("block") !== -1) {
						if (!groupResourceIds[groupName]) groupResourceIds[groupName] = [];
						groupResourceIds[groupName].push(resourceId);
					}
				});
			}

			// 3. Build and send payloads for each group
			function sendGroupUpdate(groupId, payload) {
				var token = new CiscoSecureAccessGetToken().getLatestAccessToken();
				var restMsg = new sn_ws.RESTMessageV2('Cisco Secure Access Private Resources', 'Private Put Method');
				restMsg.setHttpMethod('PUT');
				restMsg.setRequestHeader("Content-Type", "application/json");
				restMsg.setRequestHeader("Accept", "application/json");
				restMsg.setRequestHeader("Authorization", "Bearer " + token);
				restMsg.setStringParameterNoEscape('id', groupId);
				restMsg.setRequestBody(JSON.stringify(payload));
				var response = restMsg.execute();
				gs.info("[Cisco Secure Access - PR] Sent group update for groupId=" + groupId + ". Status: " + response.getStatusCode());
				gs.info("[Cisco Secure Access - PR] Response: " + response.getBody());
			}

			Object.keys(groupMap).forEach(function(groupName) {
				var group = groupMap[groupName];
				var resourceIds = groupResourceIds[groupName] || [];
				if (group.id && resourceIds.length > 0) {
					var payload = {
						name: groupName,
						description: group.desc,
						resourceIds: resourceIds
					};
					sendGroupUpdate(group.id, payload);
				}
			});

			gs.info("[Cisco Secure Access - PR] - CSA Private Resource Approval Processing completed.");
		} catch (ex) {
			gs.error("[Cisco Secure Access - PR] - Error in processing: " + ex.message);
		}
	},

	type: 'Cisco_Secure_Access_App_Approval_Processing_Private_Resources'
};
